import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Data Types","description":"","frontmatter":{"title":"Data Types"},"headers":[],"relativePath":"data-types/index.md","filePath":"data-types/index.md"}'),i={name:"data-types/index.md"};function p(l,a,o,r,c,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="data-types" tabindex="-1">Data Types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data Types&quot;">​</a></h1><p>Fault relies on simple data types. Numeric types--Integers and Floats, Boolean types, &quot;Solvables&quot;--Unknowns and Uncertains.</p><p>The type checker deduces data types from the grammar and does not need any type hints.</p><h2 id="all-numbers-are-reals" tabindex="-1">All Numbers Are Reals <a class="header-anchor" href="#all-numbers-are-reals" aria-label="Permalink to &quot;All Numbers Are Reals&quot;">​</a></h2><p>Fault converts all integers into reals (floats, specifically doubles) before generating SMT. This is what ran fastest in the early performance tests of various SMT models.</p><h2 id="booleans" tabindex="-1">Booleans <a class="header-anchor" href="#booleans" aria-label="Permalink to &quot;Booleans&quot;">​</a></h2><p>One can define a Boolean in Fault in two ways. The first is a traditional boolean value:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def node = stock{</span></span>
<span class="line"><span>    property1: true,</span></span>
<span class="line"><span>    property2: false,</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Strings are treated as booleans with the string value used as a description of the rule expressed by the variable</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s = &quot;United States Postal Service&quot;;</span></span>
<span class="line"><span>t = &quot;Postal Regulatory Commission&quot;;</span></span>
<span class="line"><span>u = &quot;the Government Accountability Office&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>independentEst = !s &amp;&amp; !t &amp;&amp; !u;</span></span></code></pre></div><h2 id="unknowns" tabindex="-1">Unknowns <a class="header-anchor" href="#unknowns" aria-label="Permalink to &quot;Unknowns&quot;">​</a></h2><p>The first draft of the model may define stocks with numeric values, but you can also leave them undefined and have the solver figure it out for you.</p><p>For example, we could define the cache like this</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec cache;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const table = unknown();</span></span>
<span class="line"><span>const memory = unknown();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def resources = stock{</span></span>
<span class="line"><span>    blocks: unknown(),</span></span>
<span class="line"><span>    table: unknown(),</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>assert resources.blocks &lt; memory;</span></span>
<span class="line"><span>assert resources.table &lt;= table;</span></span></code></pre></div><p>And the solver would assign values to those variables that satisfied the model (in other words, found a failure case).</p><p>Unknowns can be declared explicitly with <code>unknown()</code> but also implicitly by just not assigning the variable a value when declaring it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const table;</span></span>
<span class="line"><span>const memory;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def resources = stock{</span></span>
<span class="line"><span>    blocks,</span></span>
<span class="line"><span>    table,</span></span>
<span class="line"><span>};</span></span></code></pre></div><h2 id="uncertains" tabindex="-1">Uncertains <a class="header-anchor" href="#uncertains" aria-label="Permalink to &quot;Uncertains&quot;">​</a></h2><p>Alternatively sometimes the exact value is unknown but there are a range of values that are reasonable and anything out of that scope is unlikely.</p><p>There are two ways to do this in Fault. The first is to define <a href="./../invariants/assumptions.html">assumptions</a> specifying that the variable is greater than or less than certain ranges.</p><p>The second way is to declare the variable as <code>uncertain</code> which will allow those out of range solutions but calculate the probability of the value actually happening.</p><p>Uncertain values take two arguments. The mean and the sigma (standard deviation). For example changing the cache spec in the repl model to this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def resources = stock{</span></span>
<span class="line"><span>    blocks: uncertain(1,.5),</span></span>
<span class="line"><span>    table: unknown(),</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Will return results with annotations of the probabilities in parenthesis:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cache_r_machine_blocks</span></span>
<span class="line"><span>-&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 1.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 1.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 1.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 1.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 0.500000 (0.483941) -&gt; 1.500000 (0.483941) -&gt; 0.500000 (0.483941)</span></span></code></pre></div><p>For the time being Uncertains assume a normal distribution. Future updates may offer more options or the ability to restrict improbable values from the solution space.</p><h2 id="constrained-numeric-types" tabindex="-1">Constrained Numeric Types <a class="header-anchor" href="#constrained-numeric-types" aria-label="Permalink to &quot;Constrained Numeric Types&quot;">​</a></h2><p>These types tell the solver to restrict a value to a specific numeric domain.</p><h3 id="natural-n" tabindex="-1"><code>natural(n)</code> <a class="header-anchor" href="#natural-n" aria-label="Permalink to &quot;\`natural(n)\`&quot;">​</a></h3><p>A natural number — a non-negative integer starting from <code>n</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def q = stock{</span></span>
<span class="line"><span>    size: natural(0),</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Useful when a quantity is inherently countable and cannot be negative or fractional (queue depth, retry count, etc.).</p><h3 id="whole" tabindex="-1"><code>whole()</code> <a class="header-anchor" href="#whole" aria-label="Permalink to &quot;\`whole()\`&quot;">​</a></h3><p>A whole number — a non-negative integer with no specified starting value. The solver picks any whole number.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def t = stock{</span></span>
<span class="line"><span>    ticks: whole(),</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Similar to <code>natural(0)</code> but signals intent more clearly when the starting value doesn&#39;t matter.</p><h3 id="int-and-float" tabindex="-1"><code>int()</code> and <code>float()</code> <a class="header-anchor" href="#int-and-float" aria-label="Permalink to &quot;\`int()\` and \`float()\`&quot;">​</a></h3><p>Constrain a field to the integer or float domain respectively, without restricting the sign:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def sensor = stock{</span></span>
<span class="line"><span>    reading: float(),</span></span>
<span class="line"><span>    offset: int(),</span></span>
<span class="line"><span>};</span></span></code></pre></div><h2 id="parameterized-values-param" tabindex="-1">Parameterized Values: <code>param()</code> <a class="header-anchor" href="#parameterized-values-param" aria-label="Permalink to &quot;Parameterized Values: \`param()\`&quot;">​</a></h2><p><code>param()</code> marks a field as a parameter for the <a href="./../installation/config.html">template mode</a> (<code>-m template</code>). The Fault compiler will generate a <code>.params.json</code> file with these fields, and the <code>fault render</code> command substitutes concrete values at model-check time.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def limits = stock{</span></span>
<span class="line"><span>    threshold: param(),</span></span>
<span class="line"><span>    capacity: param(),</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>This lets you check the same model against multiple parameter sets without recompiling.</p>`,43)])])}const m=e(i,[["render",p]]);export{u as __pageData,m as default};
